import { useRef, useCallback, memo, useEffect, useState } from 'react';
import { ChevronLeft, ChevronRight, ArrowRight } from 'lucide-react';
import { Link } from 'react-router-dom';
import MediaCard from './MediaCard';
import type { MediaItem } from '../lib/tmdb';

interface Props {
  title: string;
  items: MediaItem[];
  mediaType?: 'movie' | 'tv';
  viewAllLink?: string;
  isTop10?: boolean;
  showProgress?: boolean;
}

// Debounce resize checks to prevent excessive re-renders
let resizeTimeout: ReturnType<typeof setTimeout> | null = null;

function MediaRowInner({ title, items, mediaType, viewAllLink, isTop10, showProgress }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  const [showArrows, setShowArrows] = useState(false);

  const scroll = useCallback((dir: 'left' | 'right') => {
    if (!ref.current) return;
    const amount = ref.current.clientWidth * 0.75;
    ref.current.scrollBy({ left: dir === 'left' ? -amount : amount, behavior: 'smooth' });
  }, []);

  // Check if scrolling is needed (debounced resize)
  useEffect(() => {
    const checkScroll = () => {
      if (!ref.current) return;
      setShowArrows(ref.current.scrollWidth > ref.current.clientWidth);
    };
    checkScroll();
    
    // Use ResizeObserver if available, fallback to window resize
    if (ref.current && 'ResizeObserver' in window) {
      const observer = new ResizeObserver(checkScroll);
      observer.observe(ref.current);
      return () => observer.disconnect();
    }
    
    window.addEventListener('resize', checkScroll, { passive: true });
    return () => window.removeEventListener('resize', checkScroll);
  }, [items]);

  if (!items.length) return null;

  // Memoized card widths to avoid recalculation
  const cardWidth = isTop10
    ? 'clamp(112px, 12vw, 160px)'
    : showProgress
      ? 'clamp(128px, 14vw, 192px)'
      : 'clamp(160px, 18vw, 208px)';

  return (
    <section 
      className="relative mb-8 group/row"
      style={{ contain: 'style layout' }}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-3 sm:mb-4">
        <h2 className="text-white font-bold text-sm sm:text-base md:text-lg" style={{ fontSize: 'clamp(1rem, 1.5vw, 1.25rem)' }}>{title}</h2>
        <div className="flex items-center gap-2">
          {viewAllLink && (
            <Link
              to={viewAllLink}
              className="text-emerald-400 hover:text-emerald-300 text-xs sm:text-sm font-medium flex items-center gap-1 transition-colors"
            >
              View all <ArrowRight size={14} />
            </Link>
          )}
          {!isTop10 && showArrows && (
            <div className="flex gap-1 opacity-0 group-hover/row:opacity-100 transition-opacity">
              <button
                onClick={() => scroll('left')}
                className="p-2 rounded-lg text-white/50 hover:text-white hover:bg-white/10 transition-all active:scale-95"
                aria-label="Scroll left"
              >
                <ChevronLeft size={18} />
              </button>
              <button
                onClick={() => scroll('right')}
                className="p-2 rounded-lg text-white/50 hover:text-white hover:bg-white/10 transition-all active:scale-95"
                aria-label="Scroll right"
              >
                <ChevronRight size={18} />
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Single-row horizontal scroll */}
      <div
        ref={ref}
        className="flex gap-2 sm:gap-3 overflow-x-auto pb-2 snap-x snap-mandatory"
        style={{ 
          scrollbarWidth: 'none', 
          msOverflowStyle: 'none',
          contain: 'style'
        }}
      >
        {items.map((item, index) => (
          <div
            key={item.id}
            className="shrink-0 snap-start flex-shrink-0"
            style={{ width: cardWidth }}
          >
            <MediaCard
              item={item}
              mediaType={mediaType}
              index={isTop10 ? index : undefined}
              viewMode="grid"
            />
          </div>
        ))}
      </div>
    </section>
  );
}

export default memo(MediaRowInner);